                            { "q": "¿La Ley 16/2023 se aplica a entidades privadas que prestan servicios públicos?", "ops": ["No, solo se aplica a entidades públicas.", "Sí, si el tratamiento de datos está vinculado a la prestación de dichos servicios.", "Solo si el servicio es de carácter educativo.", "No, salvo autorización expresa del Ararteko."], "c": 1 },
                            { "q": "¿Quién puede acordar la realización de planes de auditoría según el artículo 14 de la Ley 16/2023 de la Autoridad Vasca de Protección de Datos?", "ops": ["La presidencia de la Autoridad Vasca de Protección de Datos.", "El Tribunal Vasco de Cuentas Públicas.", "El Consejo de Gobierno del País Vasco.", "El Parlamento Vasco."], "c": 0 },
                            { "q": "¿Quién asesora a la Autoridad Vasca de Protección de Datos según el artículo 9 de la Ley 16/2023?", "ops": ["El Comité Jurídico del Parlamento Vasco.", "El Consejo Consultivo de la Autoridad Vasca de Protección de Datos.", "La Agencia Española de Protección de Datos.", "El Departamento de Gobernanza Pública del Gobierno Vasco."], "c": 1 },
                            { "q": "¿Quién nombra a la presidencia de la Autoridad Vasca de Protección de Datos?", "ops": ["El Ararteko.", "El Parlamento Vasco directamente.", "El lehendakari.", "El Gobierno Vasco, previa aprobación del Parlamento."], "c": 2 },
                            { "q": "¿Qué tipo de personal prestará servicio en la Autoridad Vasca de Protección de Datos según el artículo 5 de la Ley 16/2023?", "ops": ["Personal laboral interino.", "Personal voluntario designado por acuerdo del Parlamento Vasco.", "Funcionarios, conforme a la legislación de función pública vasca.", "Personal eventual nombrado mediante el procedimiento de libre designación."], "c": 2 },
                            { "q": "¿Quién aprueba el Estatuto de la Autoridad Vasca de Protección de Datos según el artículo 3 de la Ley 16/2023?", "ops": ["El Parlamento Vasco.", "El Gobierno Vasco.", "El Tribunal Superior de Justicia del País Vasco.", "El Ararteko."], "c": 1 },
                            { "q": "¿A qué entidad se aplica la Ley 16/2023 según el artículo 2?", "ops": ["A las administraciones forales de los territorios históricos.", "A la Agencia Española de Protección de Datos.", "A los partidos políticos del ámbito nacional.", "A las diputaciones provinciales de otras comunidades."], "c": 0 },
                            { "q": "¿Puede el personal de la Autoridad Vasca de Protección de Datos acceder a domicilios protegidos constitucionalmente en sus investigaciones?", "ops": ["Sí, libremente, por ser autoridad pública.", "Solo con consentimiento del titular o autorización judicial.", "Sí, si el domicilio pertenece a una empresa.", "No, bajo ningún concepto."], "c": 1 },
                            { "q": "¿El personal de la Autoridad Vasca de Protección de Datos debe guardar secreto sobre las informaciones que conozca en el ejercicio de sus funciones, incluso después de cesar?", "ops": ["No, solo durante el ejercicio del cargo.", "Sí, incluso después de haber cesado en sus funciones.", "Solo si firman un acuerdo de confidencialidad.", "Depende del tipo de información tratada."], "c": 1 },
                            { "q": "¿Quién dicta los actos de la Autoridad Vasca de Protección de Datos que producen efectos jurídicos sobre terceros?", "ops": ["El Consejo de la Autoridad Vasca de Protección de Datos.", "La presidencia de la Autoridad Vasca de Protección de Datos.", "El lehendakari.", "El Consejo de Gobierno del País Vasco."], "c": 1 },
                            { "q": "¿Debe la presidencia de la Autoridad Vasca de Protección de Datos elaborar un informe anual de actividades?", "ops": ["Únicamente previa solicitud del lehendakari.", "Sí, y debe enviarse al Parlamento Vasco, Gobierno Vasco y otras autoridades.", "Únicamente a requerimiento del Parlamento Vasco.", "Sí, con carácter interno y sin difusión externa."], "c": 1 }
