                            { "q": "Según el artículo 13 de la Ley 39/2015, ¿cuál es uno de los derechos de las personas en sus relaciones con las Administraciones Públicas?", "ops": ["A ser asistidos en el uso de medios electrónicos en sus relaciones con las Administraciones Públicas.", "A recibir formación gratuita sobre procedimientos administrativos.", "A recibir información pero solo en castellano.", "A acceder a cualquier expediente público sin restricciones."], "c": 0 },
                            { "q": "Según el artículo 19.1 de la Ley 39/2015, ¿cuándo será obligatoria la comparecencia de las personas ante las oficinas públicas?", "ops": ["Solo cuando así lo decida el funcionario de manera discrecional.", "Únicamente en los procedimientos sancionadores.", "Solo cuando esté prevista en una norma con rango de ley.", "En cualquier momento que lo solicite la Administración por teléfono."], "c": 2 },
                            { "q": "Según el artículo 14.3 de la Ley 39/2015, ¿puede la Administración obligar a ciertas personas físicas a relacionarse con ella por medios electrónicos?", "ops": ["No, las personas físicas nunca pueden ser obligadas.", "Sí, para determinados procedimientos y colectivos que por capacidad técnica tengan garantizado el acceso.", "Sí, de manera general para cualquier trámite a partir de 2024.", "Solo si lo autoriza previamente un juez de lo contencioso."], "c": 1 },
                            { "q": "Según el artículo 53.1.c de la Ley 39/2015, ¿qué derecho tienen los interesados si deciden no aportar documentos que ya están en manos de la Administración?", "ops": ["A que la Administración los recabe electrónicamente a través de sus redes corporativas.", "A que se archive el procedimiento por falta de documentación.", "A aportar una declaración jurada sustitutiva en todo caso.", "A paralizar los plazos del procedimiento de forma indefinida."], "c": 0 },
                            { "q": "Según el artículo 15.3 de la Ley 39/2015, ¿en qué lengua se tramitarán los procedimientos instruidos por la Administración General del Estado?", "ops": ["Exclusivamente en castellano.", "En castellano, pero los interesados podrán usar la lengua cooficial en el territorio de la CCAA.", "Siempre en la lengua cooficial de la Comunidad Autónoma correspondiente.", "En cualquier lengua de la Unión Europea si el interesado es extranjero."], "c": 1 },
                            { "q": "Según el artículo 16.3 de la Ley 39/2015, ¿qué emitirá el registro electrónico de cada Administración para garantizar la presentación?", "ops": ["Un recibo firmado físicamente por el registrador.", "Un recibo consistente en una copia autenticada del documento.", "Un recibo electrónico con los datos de la presentación, incluyendo fecha, hora y número de entrada.", "Un mensaje de texto de confirmación sin validez jurídica."], "c": 2 },
                            { "q": "Según el artículo 53.1.g de la Ley 39/2015, ¿qué derecho de obtención tienen los interesados respecto a las copias de documentos?", "ops": ["A obtener copia sellada de los documentos que presenten y de las resoluciones del procedimiento.", "A obtener copias gratuitas ilimitadas de cualquier expediente de la Administración.", "A solicitar copias únicamente tras el archivo definitivo del expediente.", "A exigir copias en formato físico en su domicilio en un plazo de 24 horas."], "c": 0 },
                            { "q": "Según el artículo 13.b de la Ley 39/2015, ¿qué derecho tienen las personas respecto a las autoridades y personal al servicio de las AAPP?", "ops": ["A exigir un trato preferente en cualquier circunstancia.", "A recibir un trato respetuoso y deferente, y a que faciliten el ejercicio de sus derechos.", "A evaluar individualmente el rendimiento del personal funcionario.", "A mantener reuniones privadas sin registro con los instructores."], "c": 1 },
                            { "q": "Según el artículo 19.2 de la Ley 39/2015, ¿qué debe constar expresamente en la citación para una comparecencia obligatoria?", "ops": ["El nombre de todos los funcionarios de la oficina.", "El objeto, lugar, fecha, hora y los efectos de la no comparecencia.", "El presupuesto asignado al departamento administrativo.", "Los datos personales del funcionario responsable."], "c": 1 },
                            { "q": "Según el artículo 16.1 de la Ley 39/2015, ¿qué función tiene el registro electrónico general de cada Administración?", "ops": ["Hacer constar el asiento de todo documento que sea presentado o que se remita a otras Administraciones o particulares.", "Gestionar exclusivamente los documentos internos de la Administración.", "Almacenar físicamente los documentos dirigidos a particulares.", "Todas son correctas."], "c": 0 },
                            { "q": "Según el artículo 16.2 de la Ley 39/2015, ¿cómo se ordenan los asientos en el registro electrónico?", "ops": ["Según la prioridad del trámite administrativo.", "Respecto al orden temporal de recepción o salida de los documentos, asignando un número correlativo.", "Según la urgencia manifestada por el interesado.", "Siguiendo un criterio aleatorio asignado por el sistema."], "c": 1 },
                            { "q": "Según el artículo 16.4 de la Ley 39/2015, ¿dónde pueden presentarse los documentos dirigidos a los órganos de las Administraciones Públicas?", "ops": ["Solo en el registro electrónico de la Administración General del Estado.", "En el registro electrónico de la Administración u Organismo al que se dirijan, así como en los restantes registros oficiales, oficinas de Correos, consulados y oficinas de asistencia.", "Únicamente en las oficinas presenciales de asistencia en materia de registros de la CCAA.", "En cualquier servicio de mensajería privada con certificación digital."], "c": 1 }
